// Pastel - color tool reimplementation
mod color;
mod colornames;
mod commands;
mod ansi;

use std::process;
use clap::{Parser, Subcommand};
use commands::*;
use color::ColorMode;

#[derive(Parser)]
#[command(
    name = "pastel",
    about = "A command-line tool to generate, analyze, convert and manipulate colors",
    version = "0.11.0",
    disable_help_subcommand = false,
)]
struct Cli {
    #[arg(long = "color-picker", help = "Use a specific tool to pick the colors",
        value_name = "color-picker",
        value_parser = ["gpick", "xcolor", "wcolor", "grabc", "colorpicker", "chameleon", "kcolorchooser", "zenity", "yad", "hyprpicker", "gdbus"]
    )]
    color_picker: Option<String>,

    #[arg(short = 'f', long = "force-color", help = "Alias for --mode=24bit")]
    force_color: bool,

    #[arg(short = 'm', long = "color-mode", help = "Specify the terminal color mode: 24bit, 8bit, off, *auto*",
        value_name = "mode")]
    color_mode: Option<String>,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    #[command(about = "Display information about the given color")]
    Color {
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Simulate a color under a certain colorblindness profile")]
    Colorblind {
        #[arg(value_name = "type", value_parser = ["prot", "deuter", "trit"])]
        cb_type: String,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Check if your terminal emulator supports 24-bit colors.")]
    Colorcheck,
    #[command(about = "Get the complementary color (hue rotated by 180°)")]
    Complement {
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Darken color by a specified amount")]
    Darken {
        #[arg(value_name = "amount")]
        amount: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Decrease color saturation by a specified amount")]
    Desaturate {
        #[arg(value_name = "amount")]
        amount: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Generate a set of visually distinct colors")]
    Distinct {
        #[arg(value_name = "count", default_value = "10")]
        count: usize,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Convert a color to the given format")]
    Format {
        #[arg(value_name = "type", default_value = "hex",
            value_parser = ["rgb", "rgb-float", "rgb-r", "rgb-g", "rgb-b", "hex", "hsl", "hsl-hue",
                "hsl-saturation", "hsl-lightness", "hsv", "hsv-hue", "hsv-saturation", "hsv-value",
                "lch", "lch-lightness", "lch-chroma", "lch-hue", "oklch", "oklch-lightness",
                "oklch-chroma", "oklch-hue", "lab", "lab-a", "lab-b", "oklab", "oklab-l", "oklab-a",
                "oklab-b", "luminance", "brightness", "ansi-8bit", "ansi-24bit", "ansi-8bit-value",
                "ansi-8bit-escapecode", "ansi-24bit-escapecode", "cmyk", "name"])]
        format_type: String,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Generate an interpolating sequence of colors")]
    Gradient {
        #[arg(short = 'n', long = "number", value_name = "count", default_value = "10")]
        count: usize,
        #[arg(short = 's', long = "colorspace", value_name = "name", default_value = "Lab",
            value_parser = ["Lab", "LCh", "RGB", "HSL", "OkLab"])]
        colorspace: String,
        #[arg(value_name = "color", required = true)]
        colors: Vec<String>,
    },
    #[command(about = "Create a gray tone from a given lightness")]
    Gray {
        #[arg(value_name = "lightness")]
        lightness: f64,
    },
    #[command(about = "Lighten color by a specified amount")]
    Lighten {
        #[arg(value_name = "amount")]
        amount: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Show a list of available color names")]
    List {
        #[arg(short = 's', long = "sort", value_name = "sort-order", default_value = "hue",
            value_parser = ["brightness", "luminance", "hue", "chroma", "random"])]
        sort: String,
    },
    #[command(about = "Mix two colors in the given colorspace")]
    Mix {
        #[arg(short = 's', long = "colorspace", value_name = "name", default_value = "Lab",
            value_parser = ["Lab", "LCh", "RGB", "HSL", "OkLab"])]
        colorspace: String,
        #[arg(short = 'f', long = "fraction", value_name = "fraction", default_value = "0.5")]
        fraction: f64,
        #[arg(value_name = "color", required = true)]
        colors: Vec<String>,
    },
    #[command(about = "Print colored text using ANSI escape sequences")]
    Paint {
        #[arg(short = 'o', long = "on", value_name = "bg-color")]
        bg_color: Option<String>,
        #[arg(short = 'b', long = "bold")]
        bold: bool,
        #[arg(short = 'i', long = "italic")]
        italic: bool,
        #[arg(short = 'u', long = "underline")]
        underline: bool,
        #[arg(short = 'n', long = "no-newline")]
        no_newline: bool,
        #[arg(value_name = "color", required = true)]
        color: String,
        #[arg(value_name = "text")]
        text: Vec<String>,
    },
    #[command(about = "Interactively pick a color from the screen (pipette)")]
    Pick,
    #[command(about = "Generate a list of random colors")]
    Random {
        #[arg(short = 's', long = "strategy", value_name = "strategy", default_value = "vivid",
            value_parser = ["vivid", "rgb", "gray", "lch_hue"])]
        strategy: String,
        #[arg(short = 'n', long = "number", value_name = "count", default_value = "10")]
        count: usize,
    },
    #[command(about = "Rotate the hue channel by the specified angle")]
    Rotate {
        #[arg(value_name = "degrees")]
        degrees: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Increase color saturation by a specified amount")]
    Saturate {
        #[arg(value_name = "amount")]
        amount: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Set a color property to a specific value")]
    Set {
        #[arg(value_name = "property",
            value_parser = ["lightness", "hue", "chroma", "lab-a", "lab-b", "oklab-l", "oklab-a",
                "oklab-b", "red", "green", "blue", "hsl-hue", "hsl-saturation", "hsl-lightness", "alpha"])]
        property: String,
        #[arg(value_name = "value")]
        value: f64,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(name = "sort-by", about = "Sort colors by the given property")]
    SortBy {
        #[arg(value_name = "sort-order", default_value = "hue",
            value_parser = ["brightness", "luminance", "hue", "chroma", "random"])]
        sort_order: String,
        #[arg(short = 'r', long = "reverse")]
        reverse: bool,
        #[arg(short = 'u', long = "unique")]
        unique: bool,
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(about = "Get a readable text color for the given background color")]
    Textcolor {
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
    #[command(name = "to-gray", about = "Completely desaturate a color (preserving luminance)")]
    ToGray {
        #[arg(value_name = "color")]
        colors: Vec<String>,
    },
}

fn determine_color_mode(cli: &Cli) -> ColorMode {
    if cli.force_color {
        return ColorMode::TrueColor;
    }

    // Check explicit CLI option
    if let Some(mode_str) = &cli.color_mode {
        return match mode_str.as_str() {
            "24bit" => ColorMode::TrueColor,
            "8bit" => ColorMode::EightBit,
            "off" => ColorMode::Off,
            "auto" => detect_color_mode(),
            _ => detect_color_mode(),
        };
    }

    // Check environment variable
    if let Ok(mode_str) = std::env::var("PASTEL_COLOR_MODE") {
        return match mode_str.as_str() {
            "24bit" => ColorMode::TrueColor,
            "8bit" => ColorMode::EightBit,
            "off" => ColorMode::Off,
            "auto" => detect_color_mode(),
            _ => detect_color_mode(),
        };
    }

    detect_color_mode()
}

fn detect_color_mode() -> ColorMode {
    // Check if stdout is a tty
    if !atty::is_atty_stdout() {
        return ColorMode::Off;
    }

    // Check COLORTERM env var for 24-bit support
    if let Ok(colorterm) = std::env::var("COLORTERM") {
        let ct = colorterm.to_lowercase();
        if ct == "truecolor" || ct == "24bit" {
            return ColorMode::TrueColor;
        }
    }

    ColorMode::EightBit
}

fn atty_stdout() -> bool {
    use std::os::unix::io::AsRawFd;
    unsafe { libc::isatty(std::io::stdout().as_raw_fd()) != 0 }
}

fn main() {
    let cli = Cli::parse();
    let color_mode = determine_color_mode(&cli);

    let result = match cli.command {
        None => {
            // Print help
            let mut cmd = Cli::command();
            cmd.print_help().unwrap();
            println!();
            return;
        }
        Some(Commands::Color { colors }) => {
            run_color(&colors, color_mode)
        }
        Some(Commands::Colorblind { cb_type, colors }) => {
            run_colorblind(&cb_type, &colors)
        }
        Some(Commands::Colorcheck) => {
            run_colorcheck(color_mode)
        }
        Some(Commands::Complement { colors }) => {
            run_complement(&colors)
        }
        Some(Commands::Darken { amount, colors }) => {
            run_darken(amount, &colors)
        }
        Some(Commands::Desaturate { amount, colors }) => {
            run_desaturate(amount, &colors)
        }
        Some(Commands::Distinct { count, colors }) => {
            run_distinct(count, &colors)
        }
        Some(Commands::Format { format_type, colors }) => {
            run_format(&format_type, &colors)
        }
        Some(Commands::Gradient { count, colorspace, colors }) => {
            run_gradient(count, &colorspace, &colors)
        }
        Some(Commands::Gray { lightness }) => {
            run_gray(lightness)
        }
        Some(Commands::Lighten { amount, colors }) => {
            run_lighten(amount, &colors)
        }
        Some(Commands::List { sort }) => {
            run_list(&sort, color_mode)
        }
        Some(Commands::Mix { colorspace, fraction, colors }) => {
            run_mix(&colorspace, fraction, &colors)
        }
        Some(Commands::Paint { bg_color, bold, italic, underline, no_newline, color, text }) => {
            run_paint(&color, bg_color.as_deref(), bold, italic, underline, no_newline, &text, color_mode)
        }
        Some(Commands::Pick) => {
            run_pick()
        }
        Some(Commands::Random { strategy, count }) => {
            run_random(&strategy, count)
        }
        Some(Commands::Rotate { degrees, colors }) => {
            run_rotate(degrees, &colors)
        }
        Some(Commands::Saturate { amount, colors }) => {
            run_saturate(amount, &colors)
        }
        Some(Commands::Set { property, value, colors }) => {
            run_set(&property, value, &colors)
        }
        Some(Commands::SortBy { sort_order, reverse, unique, colors }) => {
            run_sort_by(&sort_order, reverse, unique, &colors)
        }
        Some(Commands::Textcolor { colors }) => {
            run_textcolor(&colors)
        }
        Some(Commands::ToGray { colors }) => {
            run_to_gray(&colors)
        }
    };

    if let Err(e) = result {
        eprintln!("[pastel error]: {}", e);
        process::exit(1);
    }
}
