use std::fmt;

#[derive(Clone, Debug, PartialEq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub alpha: Option<f64>, // None means fully opaque (1.0)
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum ColorMode {
