    }

    pub fn new_rgba(r: u8, g: u8, b: u8, alpha: f64) -> Self {
        Color { r, g, b, alpha: Some(alpha) }
    }

    pub fn with_alpha(mut self, a: f64) -> Self {
        self.alpha = Some(a);
        self
    }

    pub fn alpha_f64(&self) -> f64 {
