            (g * 255.0).round() as u8,
            (bb * 255.0).round() as u8,
        )
    }

    pub fn to_lch(&self) -> (f64, f64, f64) {
        let (l, a, b) = self.to_lab();
        lab_to_lch(l, a, b)
    }

    pub fn from_lch(l: f64, c: f64, h: f64) -> Self {
        let (la, a, b) = lch_to_lab(l, c, h);
        Color::from_lab(la, a, b)
    }

    pub fn to_oklab(&self) -> (f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        rgb_to_oklab(r, g, b)
    }

    pub fn from_oklab(l: f64, a: f64, b: f64) -> Self {
        let (r, g, bb) = oklab_to_rgb(l, a, b);
        let r = clamp01(r);
        let g = clamp01(g);
        let bb = clamp01(bb);
