            (r * 255.0).round() as u8,
            (g * 255.0).round() as u8,
            (bb * 255.0).round() as u8,
        )
    }

    pub fn to_oklch(&self) -> (f64, f64, f64) {
        let (l, a, b) = self.to_oklab();
        let c = (a * a + b * b).sqrt();
        let h = b.atan2(a).to_degrees();
        let h = if h < 0.0 { h + 360.0 } else { h };
        (l, c, h)
    }

    pub fn from_oklch(l: f64, c: f64, h: f64) -> Self {
        let h_rad = h.to_radians();
        let a = c * h_rad.cos();
        let b = c * h_rad.sin();
