    pub fn luminance(&self) -> f64 {
        // WCAG 2.0 relative luminance
        let r = linearize(self.r as f64 / 255.0);
        let g = linearize(self.g as f64 / 255.0);
        let b = linearize(self.b as f64 / 255.0);
        0.2126 * r + 0.7152 * g + 0.0722 * b
