        let h_i = h.round() as i64;
        if let Some(alpha) = self.alpha {
            format!("hsla({},{:.1}%,{:.1}%,{})", h_i,
                round1(s * 100.0),
                round1(l * 100.0),
                format_alpha(alpha))
        } else {
            format!("hsl({},{:.1}%,{:.1}%)", h_i,
                round1(s * 100.0),
                round1(l * 100.0))
        }
    }

    pub fn to_rgb_string(&self) -> String {
        if let Some(alpha) = self.alpha {
            format!("rgba({}, {}, {}, {})", self.r, self.g, self.b, format_alpha(alpha))
        } else {
            format!("rgb({}, {}, {})", self.r, self.g, self.b)
        }
    }

    pub fn to_hsl_space_string(&self) -> String {
        let (h, s, l) = self.to_hsl();
        let h_i = h.round() as i64;
        if let Some(alpha) = self.alpha {
            format!("hsla({}, {:.1}%, {:.1}%, {})", h_i,
                round1(s * 100.0),
                round1(l * 100.0),
                format_alpha(alpha))
        } else {
            format!("hsl({}, {:.1}%, {:.1}%)", h_i,
                round1(s * 100.0),
                round1(l * 100.0))
        }
    }

    pub fn text_color(&self) -> Color {
        let lum = self.luminance();
        // WCAG contrast ratio: compare (lum + 0.05) with (0.0 + 0.05)
        // and (1.0 + 0.05) with (lum + 0.05)
        // Use white if contrast with black is better
        let contrast_white = (1.0 + 0.05) / (lum + 0.05);
        let contrast_black = (lum + 0.05) / (0.0 + 0.05);
        if contrast_white > contrast_black {
            Color::new(255, 255, 255)
        } else {
            Color::new(0, 0, 0)
        }
    }

    pub fn to_ansi8bit_value(&self) -> u8 {
        closest_ansi256(self.r, self.g, self.b)
    }
}

fn format_alpha(alpha: f64) -> String {
    if alpha == 0.5 {
        "0.5".to_string()
    } else if alpha == 1.0 {
        "1".to_string()
    } else if alpha == 0.0 {
        "0".to_string()
    } else {
        // Format with minimal decimal places
        let s = format!("{:.10}", alpha);
        let s = s.trim_end_matches('0');
        let s = s.trim_end_matches('.');
        s.to_string()
    }
}

fn round1(x: f64) -> f64 {
    (x * 10.0).round() / 10.0
}

fn linearize(v: f64) -> f64 {
    if v <= 0.04045 {
        v / 12.92
    } else {
        ((v + 0.055) / 1.055).powf(2.4)
    }
}

fn delinearize(v: f64) -> f64 {
    if v <= 0.0031308 {
        v * 12.92
    } else {
        1.055 * v.powf(1.0 / 2.4) - 0.055
    }
}

pub fn rgb_to_hsl(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;

    if max == min {
        return (0.0, 0.0, l);
    }

    let d = max - min;
    let s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };

    let h = if max == r {
        let mut h = (g - b) / d;
        if g < b { h += 6.0; }
        h / 6.0
    } else if max == g {
        ((b - r) / d + 2.0) / 6.0
    } else {
        ((r - g) / d + 4.0) / 6.0
    };

    (h * 360.0, s, l)
}

pub fn hsl_to_rgb(h: f64, s: f64, l: f64) -> (f64, f64, f64) {
    if s == 0.0 {
        return (l, l, l);
    }

    let h = h / 360.0;
    let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
    let p = 2.0 * l - q;

    let r = hue_to_rgb(p, q, h + 1.0/3.0);
    let g = hue_to_rgb(p, q, h);
    let b = hue_to_rgb(p, q, h - 1.0/3.0);

    (r, g, b)
}

fn hue_to_rgb(p: f64, q: f64, t: f64) -> f64 {
    let mut t = t;
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0/6.0 { return p + (q - p) * 6.0 * t; }
    if t < 1.0/2.0 { return q; }
    if t < 2.0/3.0 { return p + (q - p) * (2.0/3.0 - t) * 6.0; }
    p
}

pub fn rgb_to_hsv(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;

    let v = max;
    let s = if max == 0.0 { 0.0 } else { d / max };

    let h = if d == 0.0 {
        0.0
    } else if max == r {
        let mut h = (g - b) / d;
        if g < b { h += 6.0; }
        h / 6.0 * 360.0
    } else if max == g {
        ((b - r) / d + 2.0) / 6.0 * 360.0
    } else {
        ((r - g) / d + 4.0) / 6.0 * 360.0
    };

    (h, s, v)
}

// XYZ reference white D65
const XN: f64 = 0.95047;
const YN: f64 = 1.00000;
const ZN: f64 = 1.08883;

fn rgb_to_xyz(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let r = linearize(r);
    let g = linearize(g);
    let b = linearize(b);

    let x = 0.4124564 * r + 0.3575761 * g + 0.1804375 * b;
    let y = 0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
    let z = 0.0193339 * r + 0.1191920 * g + 0.9503041 * b;

    (x, y, z)
}

fn xyz_to_rgb(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let r =  3.2404542 * x - 1.5371385 * y - 0.4985314 * z;
    let g = -0.9692660 * x + 1.8760108 * y + 0.0415560 * z;
    let b =  0.0556434 * x - 0.2040259 * y + 1.0572252 * z;

    let r = delinearize(r.max(0.0));
    let g = delinearize(g.max(0.0));
    let b = delinearize(b.max(0.0));

    (r, g, b)
}

fn xyz_to_lab(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let fx = f_lab(x / XN);
    let fy = f_lab(y / YN);
    let fz = f_lab(z / ZN);

    let l = 116.0 * fy - 16.0;
    let a = 500.0 * (fx - fy);
    let b = 200.0 * (fy - fz);

    (l, a, b)
}

fn lab_to_xyz(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let fy = (l + 16.0) / 116.0;
    let fx = a / 500.0 + fy;
    let fz = fy - b / 200.0;

    let x = XN * f_lab_inv(fx);
    let y = YN * f_lab_inv(fy);
    let z = ZN * f_lab_inv(fz);

    (x, y, z)
}

fn f_lab(t: f64) -> f64 {
    const DELTA: f64 = 6.0 / 29.0;
    if t > DELTA * DELTA * DELTA {
        t.cbrt()
    } else {
        t / (3.0 * DELTA * DELTA) + 4.0 / 29.0
    }
}

fn f_lab_inv(t: f64) -> f64 {
    const DELTA: f64 = 6.0 / 29.0;
    if t > DELTA {
        t * t * t
    } else {
        3.0 * DELTA * DELTA * (t - 4.0 / 29.0)
    }
}

pub fn rgb_to_lab(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let (x, y, z) = rgb_to_xyz(r, g, b);
    xyz_to_lab(x, y, z)
}

pub fn lab_to_rgb(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let (x, y, z) = lab_to_xyz(l, a, b);
    xyz_to_rgb(x, y, z)
}

pub fn lab_to_lch(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let c = (a * a + b * b).sqrt();
    let h = b.atan2(a).to_degrees();
    let h = if h < 0.0 { h + 360.0 } else { h };
    (l, c, h)
}

pub fn lch_to_lab(l: f64, c: f64, h: f64) -> (f64, f64, f64) {
    let h_rad = h.to_radians();
    let a = c * h_rad.cos();
    let b = c * h_rad.sin();
    (l, a, b)
}

// OkLab conversions
pub fn rgb_to_oklab(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let r = linearize(r);
    let g = linearize(g);
    let b = linearize(b);

    let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
    let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
    let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;

    let l = l.cbrt();
    let m = m.cbrt();
    let s = s.cbrt();

    let ll = 0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s;
    let a  = 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s;
    let bb = 0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s;

    (ll, a, bb)
}

pub fn oklab_to_rgb(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;

    let l = l_ * l_ * l_;
    let m = m_ * m_ * m_;
    let s = s_ * s_ * s_;

    let r =  4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
    let g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
    let b_val = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;

    let r = delinearize(r.max(0.0));
    let g = delinearize(g.max(0.0));
    let b_val = delinearize(b_val.max(0.0));

    (r, g, b_val)
}

pub fn clamp01(v: f64) -> f64 {
    v.max(0.0).min(1.0)
}

// ANSI 256 color lookup
pub fn closest_ansi256(r: u8, g: u8, b: u8) -> u8 {
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;

    let mut best_idx = 0u8;
    let mut best_dist = i32::MAX;

    for i in 0..=255u8 {
        let (cr, cg, cb) = ansi256_to_rgb(i);
        let cr = cr as i32;
        let cg = cg as i32;
        let cb = cb as i32;
        let dist = (r - cr) * (r - cr) + (g - cg) * (g - cg) + (b - cb) * (b - cb);
        if dist < best_dist {
            best_dist = dist;
            best_idx = i;
        }
    }

    best_idx
}

pub fn ansi256_to_rgb(idx: u8) -> (u8, u8, u8) {
    match idx {
        0 => (0, 0, 0),
        1 => (128, 0, 0),
        2 => (0, 128, 0),
        3 => (128, 128, 0),
        4 => (0, 0, 128),
        5 => (128, 0, 128),
        6 => (0, 128, 128),
        7 => (192, 192, 192),
        8 => (128, 128, 128),
        9 => (255, 0, 0),
        10 => (0, 255, 0),
        11 => (255, 255, 0),
        12 => (0, 0, 255),
        13 => (255, 0, 255),
        14 => (0, 255, 255),
        15 => (255, 255, 255),
        16..=231 => {
            let idx = idx - 16;
            let b = idx % 6;
            let g = (idx / 6) % 6;
            let r = idx / 36;
            let to_val = |v: u8| -> u8 {
                if v == 0 { 0 } else { 55 + v * 40 }
            };
            (to_val(r), to_val(g), to_val(b))
        }
        232..=255 => {
            let v = 8 + (idx - 232) as u32 * 10;
            let v = v as u8;
            (v, v, v)
        }
    }
}

// Color parsing
pub fn parse_color(s: &str) -> Result<Color, String> {
    let s = s.trim();

    // Try hex formats: #RRGGBB, #RRGGBBAA, #RGB, RRGGBB, RRGGBBAA
    if let Some(hex) = try_parse_hex(s) {
        return Ok(hex);
    }

    // Try RGB/RGBA format
    if let Some(c) = try_parse_rgb(s) {
        return Ok(c);
    }

    // Try HSL/HSLA format
    if let Some(c) = try_parse_hsl(s) {
        return Ok(c);
    }

    // Try HSV format
    if let Some(c) = try_parse_hsv(s) {
        return Ok(c);
    }

    // Try Lab format
    if let Some(c) = try_parse_lab(s) {
        return Ok(c);
    }

    // Try LCh format
    if let Some(c) = try_parse_lch(s) {
        return Ok(c);
    }

    // Try OkLab format
    if let Some(c) = try_parse_oklab(s) {
        return Ok(c);
    }

    // Try OkLCh format
    if let Some(c) = try_parse_oklch(s) {
        return Ok(c);
    }

    // Try gray format
    if let Some(c) = try_parse_gray(s) {
        return Ok(c);
    }

    // Try "R,G,B" format (no parentheses)
    if let Some(c) = try_parse_rgb_no_paren(s) {
        return Ok(c);
    }

    // Try color name (after trimming whitespace)
    if let Some(c) = crate::colornames::parse_name(s) {
        return Ok(c);
    }

    Err(format!("Could not parse color '{}'", s))
}

fn try_parse_hex(s: &str) -> Option<Color> {
    let hex = if s.starts_with('#') {
        &s[1..]
    } else {
        s
    };

    // 3-digit hex: RGB -> RRGGBB
    if hex.len() == 3 && hex.chars().all(|c| c.is_ascii_hexdigit()) {
        let r = u8::from_str_radix(&hex[0..1].repeat(2), 16).ok()?;
        let g = u8::from_str_radix(&hex[1..2].repeat(2), 16).ok()?;
        let b = u8::from_str_radix(&hex[2..3].repeat(2), 16).ok()?;
        return Some(Color::new(r, g, b));
    }

    // 6-digit hex: RRGGBB
    if hex.len() == 6 && hex.chars().all(|c| c.is_ascii_hexdigit()) {
        let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
        let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
        let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
        return Some(Color::new(r, g, b));
    }

    // 8-digit hex: RRGGBBAA
    if hex.len() == 8 && hex.chars().all(|c| c.is_ascii_hexdigit()) {
        let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
        let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
        let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
        let a = u8::from_str_radix(&hex[6..8], 16).ok()?;
        let alpha = a as f64 / 255.0;
        return Some(Color::new_rgba(r, g, b, alpha));
    }

    None
}

fn parse_float_or_pct(s: &str) -> Option<f64> {
    let s = s.trim();
    if s.ends_with('%') {
        let n: f64 = s[..s.len()-1].trim().parse().ok()?;
        Some(n / 100.0)
    } else {
        s.parse().ok()
    }
}

fn try_parse_rgb(s: &str) -> Option<Color> {
    let s_lower = s.to_lowercase();
    let (prefix, rest) = if s_lower.starts_with("rgba(") {
        ("rgba", s[5..].trim_end_matches(')'))
    } else if s_lower.starts_with("rgb(") {
        ("rgb", s[4..].trim_end_matches(')'))
    } else {
        return None;
    };

    let parts: Vec<&str> = rest.split(',').collect();
    if parts.len() == 3 || (prefix == "rgba" && parts.len() == 4) || (prefix == "rgb" && parts.len() == 3) {
        let parse_component = |p: &str| -> Option<u8> {
            let p = p.trim();
            if p.ends_with('%') {
                let n: f64 = p[..p.len()-1].trim().parse().ok()?;
                Some((n / 100.0 * 255.0).round() as u8)
            } else {
                let n: f64 = p.parse().ok()?;
                // If it's a float between 0-1, treat as float
                if n >= 0.0 && n <= 1.0 && p.contains('.') {
                    Some((n * 255.0).round() as u8)
                } else {
                    Some(n.round() as u8)
                }
            }
        };

        if parts.len() >= 3 {
            let r = parse_component(parts[0])?;
            let g = parse_component(parts[1])?;
            let b = parse_component(parts[2])?;

            if parts.len() == 4 {
                let a = parse_float_or_pct(parts[3])?;
                return Some(Color::new_rgba(r, g, b, a));
            }

            return Some(Color::new(r, g, b));
        }
    }
