    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;

    let v = max;
    let s = if max == 0.0 { 0.0 } else { d / max };

    let h = if d == 0.0 {
        0.0
    } else if max == r {
        let mut h = (g - b) / d;
        if g < b { h += 6.0; }
        h / 6.0 * 360.0
    } else if max == g {
        ((b - r) / d + 2.0) / 6.0 * 360.0
    } else {
        ((r - g) / d + 4.0) / 6.0 * 360.0
    };

    (h, s, v)
}

