// Color distance functions
pub fn delta_e_cie76(c1: &Color, c2: &Color) -> f64 {
    let (l1, a1, b1) = c1.to_lab();
    let (l2, a2, b2) = c2.to_lab();
    let dl = l1 - l2;
    let da = a1 - a2;
    let db = b1 - b2;
    (dl * dl + da * da + db * db).sqrt()
}

pub fn delta_e_ciede2000(c1: &Color, c2: &Color) -> f64 {
    let (l1, a1, b1) = c1.to_lab();
    let (l2, a2, b2) = c2.to_lab();

    let kl = 1.0;
    let kc = 1.0;
    let kh = 1.0;

    let c1_ab = (a1 * a1 + b1 * b1).sqrt();
    let c2_ab = (a2 * a2 + b2 * b2).sqrt();
    let c_avg = (c1_ab + c2_ab) / 2.0;

    let c7 = c_avg.powi(7);
    let g = 0.5 * (1.0 - (c7 / (c7 + 25.0_f64.powi(7))).sqrt());

    let a1p = a1 * (1.0 + g);
    let a2p = a2 * (1.0 + g);

    let c1p = (a1p * a1p + b1 * b1).sqrt();
    let c2p = (a2p * a2p + b2 * b2).sqrt();

    let h1p = b1.atan2(a1p).to_degrees();
    let h1p = if h1p < 0.0 { h1p + 360.0 } else { h1p };

    let h2p = b2.atan2(a2p).to_degrees();
    let h2p = if h2p < 0.0 { h2p + 360.0 } else { h2p };

    let dl_p = l2 - l1;
    let dc_p = c2p - c1p;

    let dh_p = if c1p * c2p == 0.0 {
        0.0
    } else {
        let diff = h2p - h1p;
        if diff.abs() <= 180.0 {
            diff
        } else if diff > 180.0 {
            diff - 360.0
        } else {
            diff + 360.0
        }
    };

    let dh_p = 2.0 * (c1p * c2p).sqrt() * (dh_p / 2.0).to_radians().sin();

    let l_avg = (l1 + l2) / 2.0;
    let c_avg_p = (c1p + c2p) / 2.0;

    let h_avg_p = if c1p * c2p == 0.0 {
        h1p + h2p
    } else {
        let diff = (h1p - h2p).abs();
        if diff <= 180.0 {
            (h1p + h2p) / 2.0
        } else if h1p + h2p < 360.0 {
            (h1p + h2p + 360.0) / 2.0
        } else {
            (h1p + h2p - 360.0) / 2.0
        }
    };

    let t = 1.0 
        - 0.17 * ((h_avg_p - 30.0).to_radians()).cos()
        + 0.24 * (2.0 * h_avg_p.to_radians()).cos()
        + 0.32 * ((3.0 * h_avg_p + 6.0).to_radians()).cos()
        - 0.20 * ((4.0 * h_avg_p - 63.0).to_radians()).cos();

    let sl = 1.0 + 0.015 * (l_avg - 50.0).powi(2) / (20.0 + (l_avg - 50.0).powi(2)).sqrt();
    let sc = 1.0 + 0.045 * c_avg_p;
    let sh = 1.0 + 0.015 * c_avg_p * t;

    let c7_avg = c_avg_p.powi(7);
    let rc = 2.0 * (c7_avg / (c7_avg + 25.0_f64.powi(7))).sqrt();

    let d_theta = 30.0 * (-(((h_avg_p - 275.0) / 25.0).powi(2))).exp();
    let rt = -(d_theta.to_radians() * 2.0).sin() * rc;

    let term1 = dl_p / (kl * sl);
    let term2 = dc_p / (kc * sc);
    let term3 = dh_p / (kh * sh);

    (term1 * term1 + term2 * term2 + term3 * term3 + rt * term2 * term3).sqrt()
}

// Colorblind simulation
pub fn colorblind_simulate(color: &Color, cb_type: &str) -> Color {
    let r = color.r as f64 / 255.0;
    let g = color.g as f64 / 255.0;
    let b = color.b as f64 / 255.0;

    // Convert to LMS using Hunt-Pointer-Estevez transform
    let l_lms = 17.8824 * r + 43.5161 * g + 4.11935 * b;
    let m_lms = 3.45565 * r + 27.1554 * g + 3.86714 * b;
    let s_lms = 0.0299566 * r + 0.184309 * g + 1.46709 * b;

    let (l2, m2, s2) = match cb_type {
        "prot" => {
            // Protanopia: L cones absent
            (
                0.0 * l_lms + 2.02344 * m_lms + -2.52581 * s_lms,
                0.0 * l_lms + 1.0 * m_lms + 0.0 * s_lms,
                0.0 * l_lms + 0.0 * m_lms + 1.0 * s_lms,
            )
        }
        "deuter" => {
            // Deuteranopia: M cones absent
            (
                1.0 * l_lms + 0.0 * m_lms + 0.0 * s_lms,
                0.494207 * l_lms + 0.0 * m_lms + 1.24827 * s_lms,
                0.0 * l_lms + 0.0 * m_lms + 1.0 * s_lms,
            )
        }
        "trit" => {
            // Tritanopia: S cones absent
            (
                1.0 * l_lms + 0.0 * m_lms + 0.0 * s_lms,
                0.0 * l_lms + 1.0 * m_lms + 0.0 * s_lms,
                -0.395913 * l_lms + 0.801109 * m_lms + 0.0 * s_lms,
            )
        }
        _ => (l_lms, m_lms, s_lms),
    };

    // Convert back from LMS to RGB (inverse HPE)
    let r2 = 0.0809444479 * l2 + -0.130504409 * m2 + 0.116721066 * s2;
    let g2 = -0.0102485335 * l2 + 0.0540193266 * m2 + -0.113614708 * s2;
    let b2 = -0.000365296938 * l2 + -0.00412161469 * m2 + 0.693511405 * s2;

    let r2 = clamp01(r2);
    let g2 = clamp01(g2);
    let b2 = clamp01(b2);

    Color::new(
        (r2 * 255.0).round() as u8,
        (g2 * 255.0).round() as u8,
        (b2 * 255.0).round() as u8,
    )
}

pub fn mix_colors(c1: &Color, c2: &Color, t: f64, colorspace: &str) -> Color {
    // t is fraction of c1 (base) mixed into c2
    // When t=0.5, equal mix; t=1.0 means all c1, t=0.0 means all c2
    match colorspace {
        "RGB" => {
            let r = lerp(c1.r as f64, c2.r as f64, t).round() as u8;
            let g = lerp(c1.g as f64, c2.g as f64, t).round() as u8;
            let b = lerp(c1.b as f64, c2.b as f64, t).round() as u8;
            Color::new(r, g, b)
        }
        "HSL" => {
            let (h1, s1, l1) = c1.to_hsl();
            let (h2, s2, l2) = c2.to_hsl();
            let h = lerp_hue(h1, h2, t);
            let s = lerp(s1, s2, t);
            let l = lerp(l1, l2, t);
            Color::from_hsl(h, s, l)
        }
        "LCh" => {
            let (l1, c1, h1) = c1.to_lch();
            let (l2, c2, h2) = c2.to_lch();
            let l = lerp(l1, l2, t);
            let c = lerp(c1, c2, t);
            let h = lerp_hue(h1, h2, t);
            Color::from_lch(l, c, h)
        }
        "OkLab" => {
            let (l1, a1, b1) = c1.to_oklab();
            let (l2, a2, b2) = c2.to_oklab();
            let l = lerp(l1, l2, t);
            let a = lerp(a1, a2, t);
            let b = lerp(b1, b2, t);
            Color::from_oklab(l, a, b)
        }
        _ => { // Lab
            let (l1, a1, b1) = c1.to_lab();
            let (l2, a2, b2) = c2.to_lab();
            let l = lerp(l1, l2, t);
            let a = lerp(a1, a2, t);
            let b = lerp(b1, b2, t);
            Color::from_lab(l, a, b)
        }
    }
}

fn lerp(a: f64, b: f64, t: f64) -> f64 {
    a * t + b * (1.0 - t)
}

fn lerp_hue(h1: f64, h2: f64, t: f64) -> f64 {
    // Lerp on a circle (shortest path)
    let diff = h2 - h1;
    let diff = if diff > 180.0 { diff - 360.0 } else if diff < -180.0 { diff + 360.0 } else { diff };
    let h = h1 - diff * (1.0 - t);
    // Wrap to [0, 360)
    ((h % 360.0) + 360.0) % 360.0
}

impl fmt::Display for Color {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_hsl_string())
    }
}
