// ANSI terminal color output
use crate::color::{Color, ColorMode};

pub fn color_swatch(color: &Color, mode: ColorMode) -> String {
    match mode {
        ColorMode::TrueColor => {
            format!("\x1b[38;2;{};{};{}m \x1b[0m", color.r, color.g, color.b)
        }
        ColorMode::EightBit => {
            let idx = color.to_ansi8bit_value();
            format!("\x1b[38;5;{}m \x1b[0m", idx)
        }
        ColorMode::Off => " ".to_string(),
    }
}

pub fn bg_color_swatch(color: &Color, mode: ColorMode) -> String {
    match mode {
        ColorMode::TrueColor => {
            format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", 
                color.r, color.g, color.b,
                color.r, color.g, color.b)
        }
        ColorMode::EightBit => {
            let idx = color.to_ansi8bit_value();
            format!("\x1b[38;5;{};48;5;{}m \x1b[0m", idx, idx)
        }
        ColorMode::Off => " ".to_string(),
    }
}

/// Checkerboard pattern (two colors alternating) for color border
pub fn checkerboard_cell(c1: &Color, c2: &Color, mode: ColorMode) -> String {
    match mode {
        ColorMode::TrueColor => {
            let up_char = "\u{2580}"; // ▀ upper half block
            format!("\x1b[38;2;{};{};{};48;2;{};{};{}m{}\x1b[0m",
                c1.r, c1.g, c1.b,
                c2.r, c2.g, c2.b,
                up_char)
        }
        ColorMode::EightBit => {
            let idx1 = c1.to_ansi8bit_value();
            let idx2 = c2.to_ansi8bit_value();
            let up_char = "\u{2580}";
            format!("\x1b[38;5;{};48;5;{}m{}\x1b[0m", idx1, idx2, up_char)
        }
        ColorMode::Off => " ".to_string(),
    }
}

pub fn colorize_text(text: &str, fg: &Color, bg: Option<&Color>, bold: bool, italic: bool, underline: bool, mode: ColorMode) -> String {
    match mode {
        ColorMode::Off => text.to_string(),
        ColorMode::TrueColor => {
            let mut codes = Vec::new();
            codes.push(format!("38;2;{};{};{}", fg.r, fg.g, fg.b));
            if let Some(bg_color) = bg {
                codes.push(format!("48;2;{};{};{}", bg_color.r, bg_color.g, bg_color.b));
            }
            if bold { codes.push("1".to_string()); }
            if italic { codes.push("3".to_string()); }
            if underline { codes.push("4".to_string()); }
            format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
        }
        ColorMode::EightBit => {
            let fg_idx = fg.to_ansi8bit_value();
            let mut codes = Vec::new();
            codes.push(format!("38;5;{}", fg_idx));
            if let Some(bg_color) = bg {
                let bg_idx = bg_color.to_ansi8bit_value();
                codes.push(format!("48;5;{}", bg_idx));
            }
            if bold { codes.push("1".to_string()); }
            if italic { codes.push("3".to_string()); }
            if underline { codes.push("4".to_string()); }
            format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
        }
    }
}
