pub fn run_complement(color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;
    for color in &colors {
        let (h, s, l) = color.to_hsl();
        let new_h = (h + 180.0) % 360.0;
        let result = Color::from_hsl(new_h, s, l);
        let result = if let Some(a) = color.alpha { result.with_alpha(a) } else { result };
        print_color_hsl(&result);
    }
    Ok(())
}

pub fn run_darken(amount: f64, color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;
    for color in &colors {
        let (h, s, l) = color.to_hsl();
        let new_l = clamp01(l - amount);
        let result = Color::from_hsl(h, s, new_l);
        let result = if let Some(a) = color.alpha { result.with_alpha(a) } else { result };
        print_color_hsl(&result);
    }
    Ok(())
}

pub fn run_desaturate(amount: f64, color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;
    for color in &colors {
        let (h, s, l) = color.to_hsl();
        let new_s = clamp01(s - amount);
        let result = Color::from_hsl(h, new_s, l);
        let result = if let Some(a) = color.alpha { result.with_alpha(a) } else { result };
        print_color_hsl(&result);
    }
    Ok(())
}

pub fn run_distinct(count: usize, color_args: &[String]) -> Result<()> {
    if !color_args.is_empty() {
        // Use provided colors as fixed set and output them
        let colors = collect_colors(color_args)?;
        // Distinct just outputs the given colors if they're provided
        // If count is given, limit output (or possibly use simulated annealing on remaining?)
        // Based on testing: `distinct 3 red green blue` just outputs the 3 colors
        for color in colors.iter().take(count) {
            print_color_hsl(color);
        }
        return Ok(());
    }

    // Generate `count` visually distinct colors using simulated annealing
    generate_distinct_colors(count, "CIE76")
}

fn generate_distinct_colors(count: usize, _metric: &str) -> Result<()> {
    use rand::Rng;
    let mut rng = rand::thread_rng();

    // Initialize with random vivid colors
    let mut colors: Vec<Color> = (0..count)
        .map(|_| {
            let h = rng.gen_range(0.0..360.0);
            let s = rng.gen_range(0.5..1.0);
            let l = rng.gen_range(0.3..0.7);
            Color::from_hsl(h, s, l)
        })
        .collect();

    // Simulated annealing
    let n_steps = 10000 * count;
    let mut temp = 1.0_f64;
    let cooling = (temp / 1e-6_f64).powf(1.0 / n_steps as f64);

    let total_dist = |cs: &[Color]| -> f64 {
        let mut sum = 0.0_f64;
        for i in 0..cs.len() {
            for j in (i+1)..cs.len() {
                sum += delta_e_cie76(&cs[i], &cs[j]);
            }
        }
        sum
    };

    let mut current_score = total_dist(&colors);

    for _ in 0..n_steps {
        let idx = rng.gen_range(0..count);
        let h = rng.gen_range(0.0..360.0);
        let s = rng.gen_range(0.3..1.0);
        let l = rng.gen_range(0.2..0.8);
        let candidate = Color::from_hsl(h, s, l);

        let old = colors[idx].clone();
        colors[idx] = candidate;
        let new_score = total_dist(&colors);

        if new_score > current_score || rng.gen::<f64>() < ((new_score - current_score) / temp).exp() {
            current_score = new_score;
        } else {
            colors[idx] = old;
        }

        temp /= cooling;
    }

    for color in &colors {
        print_color_hsl(color);
    }

    Ok(())
}

