fn format_color(color: &Color, fmt: &str) -> Result<String> {
    match fmt {
        "hex" => Ok(color.to_hex_string()),
        "rgb" => Ok(color.to_rgb_string()),
        "rgb-float" => {
            let r = color.r as f64 / 255.0;
            let g = color.g as f64 / 255.0;
            let b = color.b as f64 / 255.0;
            if let Some(a) = color.alpha {
                Ok(format!("rgba({:.3}, {:.3}, {:.3}, {})", r, g, b, fmt_alpha(a)))
            } else {
                Ok(format!("rgb({:.3}, {:.3}, {:.3})", r, g, b))
            }
        }
        "rgb-r" => Ok(format!("{}", color.r)),
        "rgb-g" => Ok(format!("{}", color.g)),
        "rgb-b" => Ok(format!("{}", color.b)),
        "hsl" => Ok(color.to_hsl_space_string()),
        "hsl-hue" => {
            let (h, _, _) = color.to_hsl();
            Ok(format!("{}", h.round() as i64))
        }
        "hsl-saturation" => {
            let (_, s, _) = color.to_hsl();
            Ok(format!("{:.4}", s))
        }
        "hsl-lightness" => {
            let (_, _, l) = color.to_hsl();
            Ok(format!("{:.4}", l))
        }
        "hsv" => {
            let (h, s, v) = color.to_hsv();
            Ok(format!("hsv({}, {:.1}%, {:.1}%)", h.round() as i64, round1(s*100.0), round1(v*100.0)))
        }
        "hsv-hue" => {
            let (h, _, _) = color.to_hsv();
            Ok(format!("{}", h.round() as i64))
        }
        "hsv-saturation" => {
            let (_, s, _) = color.to_hsv();
            Ok(format!("{:.4}", s))
        }
        "hsv-value" => {
            let (_, _, v) = color.to_hsv();
            Ok(format!("{:.4}", v))
        }
        "lch" => {
            let (l, c, h) = color.to_lch();
            Ok(format!("LCh({}, {}, {})", l.round() as i64, c.round() as i64, h.round() as i64))
        }
        "lch-lightness" => {
            let (l, _, _) = color.to_lch();
            Ok(format!("{:.2}", l))
        }
        "lch-chroma" => {
            let (_, c, _) = color.to_lch();
            Ok(format!("{:.2}", c))
        }
        "lch-hue" => {
            let (_, _, h) = color.to_lch();
            Ok(format!("{:.2}", h))
        }
        "lab" => {
            let (l, a, b) = color.to_lab();
            Ok(format!("Lab({}, {}, {})", l.round() as i64, a.round() as i64, signed_round(b)))
        }
        "lab-a" => {
            let (_, a, _) = color.to_lab();
            Ok(format!("{:.2}", a))
        }
        "lab-b" => {
            let (_, _, b) = color.to_lab();
            Ok(format!("{:.2}", b))
        }
        "oklab" => {
            let (l, a, b) = color.to_oklab();
            Ok(format!("OkLab({:.4}, {:.4}, {:.4})", l, a, b))
        }
        "oklab-l" => {
            let (l, _, _) = color.to_oklab();
            Ok(format!("{:.4}", l))
        }
        "oklab-a" => {
            let (_, a, _) = color.to_oklab();
            Ok(format!("{:.4}", a))
        }
        "oklab-b" => {
            let (_, _, b) = color.to_oklab();
            Ok(format!("{:.4}", b))
        }
        "oklch" => {
            let (l, c, h) = color.to_oklch();
            Ok(format!("OkLCh({:.4}, {:.4}, {:.4})", l, c, h))
        }
        "oklch-lightness" => {
            let (l, _, _) = color.to_oklch();
            Ok(format!("{:.4}", l))
        }
        "oklch-chroma" => {
            let (_, c, _) = color.to_oklch();
            Ok(format!("{:.4}", c))
        }
        "oklch-hue" => {
            let (_, _, h) = color.to_oklch();
            Ok(format!("{:.4}", h))
        }
        "luminance" => {
            Ok(format!("{:.3}", color.luminance()))
        }
        "brightness" => {
            Ok(format!("{:.3}", color.brightness()))
        }
        "ansi-8bit" => {
            let idx = color.to_ansi8bit_value();
            Ok(format!("\\x1b[38;5;{}m", idx))
        }
        "ansi-24bit" => {
            Ok(format!("\\x1b[38;2;{};{};{}m", color.r, color.g, color.b))
        }
        "ansi-8bit-value" => {
            Ok(format!("{}", color.to_ansi8bit_value()))
        }
        "ansi-8bit-escapecode" => {
            let idx = color.to_ansi8bit_value();
            // Print actual escape code (no trailing newline in the escape itself)
            Ok(format!("\x1b[38;5;{}m", idx))
        }
        "ansi-24bit-escapecode" => {
            Ok(format!("\x1b[38;2;{};{};{}m", color.r, color.g, color.b))
        }
        "cmyk" => {
            let r = color.r as f64 / 255.0;
            let g = color.g as f64 / 255.0;
            let b = color.b as f64 / 255.0;
            let k = 1.0 - r.max(g).max(b);
            if k >= 1.0 {
                Ok("cmyk(0, 0, 0, 100)".to_string())
            } else {
                let c = (1.0 - r - k) / (1.0 - k);
                let m = (1.0 - g - k) / (1.0 - k);
                let y = (1.0 - b - k) / (1.0 - k);
                Ok(format!("cmyk({}, {}, {}, {})", 
                    (c * 100.0).round() as i64,
                    (m * 100.0).round() as i64,
                    (y * 100.0).round() as i64,
                    (k * 100.0).round() as i64))
            }
        }
        "name" => {
            Ok(colornames::format_name(color))
        }
        _ => Err(format!("Unknown format: {}", fmt)),
    }
}

fn signed_round(x: f64) -> String {
    // Return "-0" for values very close to 0 but negative
    let r = x.round() as i64;
    if r == 0 && x < 0.0 {
        "-0".to_string()
    } else {
        format!("{}", r)
    }
}

pub fn run_gradient(count: usize, colorspace: &str, color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;
    if colors.len() < 2 {
        return Err("Gradient requires at least 2 colors".to_string());
    }

    // Generate `count` colors interpolating through the stops
    let stops = colors.len();
    let segments = stops - 1;

    for i in 0..count {
        let t_total = if count == 1 { 0.0 } else { i as f64 / (count - 1) as f64 };

        // Find which segment this point falls in
        let seg_t = t_total * segments as f64;
        let seg_idx = (seg_t as usize).min(segments - 1);
        let local_t = seg_t - seg_idx as f64;

        let c1 = &colors[seg_idx];
        let c2 = &colors[seg_idx + 1];

        // local_t goes 0 -> 1 from c1 to c2
        // mix_colors: t is fraction of c1, so t=1 is all c1, t=0 is all c2
        let result = mix_colors(c1, c2, 1.0 - local_t, colorspace);
        print_color_hsl(&result);
    }
    Ok(())
}

