    let make_row = |row_idx: usize, inner: Vec<String>, text: &str| -> String {
        let mut s = String::new();
        s.push_str("  "); // 2 spaces indent

        // First border pair (alternating based on row)
        let (bc1, bc2) = if row_idx % 2 == 0 {
