fn round1(x: f64) -> f64 {
    (x * 10.0).round() / 10.0
}

fn fmt_alpha(alpha: f64) -> String {
    // Produce the minimal decimal representation
    let s = format!("{:.10}", alpha);
    let s = s.trim_end_matches('0');
    let s = s.trim_end_matches('.');
    if s.is_empty() { "0".to_string() } else { s.to_string() }
}

fn find_similar_colors(color: &Color, n: usize) -> Vec<(String, Color)> {
    let mut distances: Vec<(String, Color, f64)> = colornames::CSS_COLORS
        .iter()
        .map(|&(name, r, g, b)| {
            let nc = Color::new(r, g, b);
            let dist = delta_e_cie76(color, &nc);
            (name.to_string(), nc, dist)
        })
        .collect();

    distances.sort_by(|a, b| a.2.partial_cmp(&b.2).unwrap());

    // Skip if the color is an exact match (dist == 0)
    distances.into_iter()
        .filter(|(_, nc, _)| nc.r != color.r || nc.g != color.g || nc.b != color.b)
        .take(n)
        .map(|(name, c, _)| (name, c))
        .collect()
}

