            });
        }
        line.push_str("  ");
        for _ in 0..8 {
            line.push_str(&match mode {
                ColorMode::TrueColor => format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", r2, g2, b2, r2, g2, b2),
                ColorMode::EightBit | _ => format!("\x1b[38;5;{};48;5;{}m \x1b[0m", c8_2, c8_2),
            });
        }
        line.push_str("  ");
        for _ in 0..8 {
            line.push_str(&match mode {
                ColorMode::TrueColor => format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", r3, g3, b3, r3, g3, b3),
                ColorMode::EightBit | _ => format!("\x1b[38;5;{};48;5;{}m \x1b[0m", c8_3, c8_3),
            });
        }
        println!("{}", line);
    }
    println!("{}", empty_row);

    println!("24-bit mode:");
    println!("{}", empty_row);

    for _row in 0..4 {
        let mut line = String::from("  ");
        for _ in 0..8 {
            line.push_str(&bg_color_swatch(&c24_1, mode));
        }
        line.push_str("  ");
        for _ in 0..8 {
            line.push_str(&bg_color_swatch(&c24_2, mode));
        }
        line.push_str("  ");
        for _ in 0..8 {
            line.push_str(&bg_color_swatch(&c24_3, mode));
        }
        println!("{}", line);
    }
    println!("{}", empty_row);

    println!("If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.");
    println!("The panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).");
    println!();
    println!("You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.");

    Ok(())
}

