fn set_property(color: &Color, property: &str, value: f64) -> Result<Color> {
    match property {
        "hsl-hue" => {
            let (_, s, l) = color.to_hsl();
            Ok(Color::from_hsl(value, s, l))
        }
        "hsl-saturation" => {
            let (h, _, l) = color.to_hsl();
            Ok(Color::from_hsl(h, value, l))
        }
        "hsl-lightness" => {
            let (h, s, _) = color.to_hsl();
            Ok(Color::from_hsl(h, s, value))
        }
        "hue" => {
            // LCh hue
            let (l, c, _) = color.to_lch();
            Ok(Color::from_lch(l, c, value))
        }
        "chroma" => {
            let (l, _, h) = color.to_lch();
            Ok(Color::from_lch(l, value, h))
        }
        "lightness" => {
            // LCh lightness
            let (_, c, h) = color.to_lch();
            Ok(Color::from_lch(value, c, h))
        }
        "lab-a" => {
            let (l, _, b) = color.to_lab();
            Ok(Color::from_lab(l, value, b))
        }
        "lab-b" => {
            let (l, a, _) = color.to_lab();
            Ok(Color::from_lab(l, a, value))
        }
        "oklab-l" => {
            let (_, a, b) = color.to_oklab();
            Ok(Color::from_oklab(value, a, b))
        }
        "oklab-a" => {
            let (l, _, b) = color.to_oklab();
            Ok(Color::from_oklab(l, value, b))
        }
        "oklab-b" => {
            let (l, a, _) = color.to_oklab();
            Ok(Color::from_oklab(l, a, value))
        }
        "red" => {
            let r = clamp01(value / 255.0);
            let g = color.g as f64 / 255.0;
            let b = color.b as f64 / 255.0;
            let (h, s, l) = crate::color::rgb_to_hsl(r, g, b);
            Ok(Color::from_hsl(h, s, l))
        }
        "green" => {
            let r = color.r as f64 / 255.0;
            let g = clamp01(value / 255.0);
            let b = color.b as f64 / 255.0;
            let (h, s, l) = crate::color::rgb_to_hsl(r, g, b);
            Ok(Color::from_hsl(h, s, l))
        }
        "blue" => {
            let r = color.r as f64 / 255.0;
            let g = color.g as f64 / 255.0;
            let b = clamp01(value / 255.0);
            let (h, s, l) = crate::color::rgb_to_hsl(r, g, b);
            Ok(Color::from_hsl(h, s, l))
        }
        "alpha" => {
            Ok(color.clone().with_alpha(value))
        }
        _ => Err(format!("Unknown property: {}", property)),
    }
}

pub fn run_sort_by(sort_order: &str, reverse: bool, unique: bool, color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;

    let mut sorted = colors;

    if unique {
        let mut seen: std::collections::HashSet<(u8, u8, u8)> = std::collections::HashSet::new();
        sorted.retain(|c| seen.insert((c.r, c.g, c.b)));
    }

    match sort_order {
        "hue" => sorted.sort_by(|a, b| {
            let (ha, _, _) = a.to_hsl();
            let (hb, _, _) = b.to_hsl();
            ha.partial_cmp(&hb).unwrap()
        }),
        "brightness" => sorted.sort_by(|a, b| {
            a.brightness().partial_cmp(&b.brightness()).unwrap()
        }),
        "luminance" => sorted.sort_by(|a, b| {
            a.luminance().partial_cmp(&b.luminance()).unwrap()
        }),
        "chroma" => sorted.sort_by(|a, b| {
            let (_, ca, _) = a.to_lch();
            let (_, cb, _) = b.to_lch();
            ca.partial_cmp(&cb).unwrap()
        }),
        "random" => {
            use rand::seq::SliceRandom;
            let mut rng = rand::thread_rng();
            sorted.shuffle(&mut rng);
        }
        _ => {}
    }

    if reverse {
        sorted.reverse();
    }

    for color in &sorted {
        print_color_hsl(color);
    }

    Ok(())
}

