pub fn run_to_gray(color_args: &[String]) -> Result<()> {
    let colors = collect_colors(color_args)?;
    for color in &colors {
        let lum = color.luminance();
        // Convert luminance to lightness in HSL space
        // Approximate: find l such that linearize(l) ≈ lum
        // Use binary search or Newton's method
        let l = luminance_to_lightness(lum);
        let result = Color::from_hsl(0.0, 0.0, l);
        let result = if let Some(a) = color.alpha { result.with_alpha(a) } else { result };
        print_color_hsl(&result);
    }
    Ok(())
}

fn luminance_to_lightness(lum: f64) -> f64 {
    // Find l in HSL (= CSS lightness of a gray) such that the relative luminance = lum
    // For a gray with lightness l, r=g=b=l, and luminance = linearize(l)
    // So find l such that linearize(l) = lum

    fn linearize(v: f64) -> f64 {
        if v <= 0.04045 {
            v / 12.92
        } else {
            ((v + 0.055) / 1.055).powf(2.4)
        }
    }

    // Binary search
    let mut lo = 0.0_f64;
    let mut hi = 1.0_f64;
    for _ in 0..50 {
        let mid = (lo + hi) / 2.0;
        if linearize(mid) < lum {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    (lo + hi) / 2.0
}

