pub fn collect_colors(color_args: &[String]) -> Result<Vec<Color>> {
    if color_args.is_empty() {
        // Read from stdin
        let stdin = io::stdin();
        let mut colors = Vec::new();
        for line in stdin.lock().lines() {
            let line = line.map_err(|e| e.to_string())?;
            let line = line.trim();
            if line.is_empty() { continue; }
            let c = parse_color(line)?;
            colors.push(c);
        }
        Ok(colors)
    } else {
        let mut colors = Vec::new();
        for arg in color_args {
            if arg == "-" {
                // Read one color from stdin
                let stdin = io::stdin();
                let mut line = String::new();
                stdin.lock().read_line(&mut line).map_err(|e| e.to_string())?;
                let line = line.trim();
                let c = parse_color(line)?;
                colors.push(c);
            } else {
                let c = parse_color(arg)?;
                colors.push(c);
            }
        }
        Ok(colors)
    }
}

