fn print_color_block(color: &Color, mode: ColorMode) {
    // Display the color information block
    // Format: checkerboard border around 12-wide color swatch + info text

    let light = Color::new(CHECKER_LIGHT.0, CHECKER_LIGHT.1, CHECKER_LIGHT.2);
    let dark = Color::new(CHECKER_DARK.0, CHECKER_DARK.1, CHECKER_DARK.2);

    let hex = color.to_hex_string();
    let rgb = color.to_rgb_string();
    let (h, s, l) = color.to_hsl();
    let h_i = h.round() as i64;
    let hsl_str = if let Some(alpha) = color.alpha {
        format!("hsla({}, {:.1}%, {:.1}%, {})", h_i, round1(s*100.0), round1(l*100.0), fmt_alpha(alpha))
    } else {
        format!("hsl({}, {:.1}%, {:.1}%)", h_i, round1(s*100.0), round1(l*100.0))
    };

    // Find color name
    let name_opt = colornames::parse_name(&colornames::format_name(color));
    let name_row = name_opt.map(|_| format!("Name: {}", colornames::format_name(color)));

    // Find 3 most similar colors from named colors
    let similar = find_similar_colors(color, 3);

    let border_width = 16; // total: 2 border cells + 12 color cells + 2 border cells = 16

    // Build the 8 rows
    let text_width = 42; // width for text content

    // Helper to make a checkerboard border row
    let make_row = |row_idx: usize, inner: Vec<String>, text: &str| -> String {
        let mut s = String::new();
        s.push_str("  "); // 2 spaces indent

        // First border pair (alternating based on row)
        let (bc1, bc2) = if row_idx % 2 == 0 {
            (&light, &dark)
        } else {
            (&dark, &light)
        };
        s.push_str(&checkerboard_cell(bc1, bc2, mode));
        s.push_str(&checkerboard_cell(bc2, bc1, mode));

        // Inner content (12 chars)
        for cell in &inner {
            s.push_str(cell);
        }

        // Last border pair
        s.push_str(&checkerboard_cell(bc1, bc2, mode));
        s.push_str(&checkerboard_cell(bc2, bc1, mode));

        if !text.is_empty() {
            // Pad text to fixed width
            s.push_str(&format!("  {:<text_w$}", text, text_w = text_width));
        } else {
            s.push_str(&format!("  {:<text_w$}", "", text_w = text_width));
        }

        s
    };

    // Create color cells (12 wide)
    let color_cells: Vec<String> = (0..12).map(|_| bg_color_swatch(color, mode)).collect();
    let border_cells: Vec<String> = (0..12).map(|i| {
        let (c1, c2) = if i % 2 == 0 { (&light, &dark) } else { (&dark, &light) };
        checkerboard_cell(c1, c2, mode)
    }).collect();

    println!();

    // Row 0: top border
    println!("{}", make_row(0, border_cells.clone(), name_row.as_deref().unwrap_or(&format!("Hex: {}", hex))));

    let info_rows = if name_opt.is_some() {
        vec![
            format!("Hex: {}", hex),
            format!("RGB: {}", rgb),
            format!("HSL: {}", hsl_str),
            "".to_string(),
        ]
    } else {
        vec![
            format!("RGB: {}", rgb),
            format!("HSL: {}", hsl_str),
            "".to_string(),
            "".to_string(),
        ]
    };

    // Rows 1-5: color display + info
    for (i, info) in info_rows.iter().enumerate() {
        println!("{}", make_row(i + 1, color_cells.clone(), info));
    }

    // Row 5: "Most similar:" header
    println!("{}", make_row(5, color_cells.clone(), "Most similar:"));

    // Rows 6-8: similar colors
    for (name, sim_color) in similar.iter() {
        let sim_cells: Vec<String> = (0..5).map(|_| bg_color_swatch(sim_color, mode)).collect();
        let sim_row_text = format!("   {}", " ".repeat(0));

        let mut row = String::from("  ");
        let row_idx = 6;
        let (bc1, bc2) = (&light, &dark);
        row.push_str(&checkerboard_cell(bc1, bc2, mode));
        row.push_str(&checkerboard_cell(bc2, bc1, mode));
        for _ in 0..12 {
            row.push_str(&bg_color_swatch(color, mode));
        }
        row.push_str(&checkerboard_cell(bc1, bc2, mode));
        row.push_str(&checkerboard_cell(bc2, bc1, mode));

        // Similarity entry
        row.push_str("   ");
        for _ in 0..5 {
            row.push_str(&bg_color_swatch(sim_color, mode));
        }
        let name_padded = format!(" {:<33}", name);
        row.push_str(&name_padded);

