pub fn run_list(sort: &str, mode: ColorMode) -> Result<()> {
    let mut entries: Vec<(&str, Color)> = colornames::CSS_COLORS
        .iter()
        .map(|&(name, r, g, b)| (name, Color::new(r, g, b)))
        .collect();

    match sort {
        "hue" => {
            entries.sort_by(|(_, a), (_, b)| {
                let (ha, _, _) = a.to_hsl();
                let (hb, _, _) = b.to_hsl();
                ha.partial_cmp(&hb).unwrap()
            });
        }
        "brightness" => {
            entries.sort_by(|(_, a), (_, b)| {
                a.brightness().partial_cmp(&b.brightness()).unwrap()
            });
        }
        "luminance" => {
            entries.sort_by(|(_, a), (_, b)| {
                a.luminance().partial_cmp(&b.luminance()).unwrap()
            });
        }
        "chroma" => {
            entries.sort_by(|(_, a), (_, b)| {
                let (_, _, ca) = a.to_lch();
                let (_, _, cb) = b.to_lch();
                ca.partial_cmp(&cb).unwrap()
            });
        }
        "random" => {
            use rand::seq::SliceRandom;
            let mut rng = rand::thread_rng();
            entries.shuffle(&mut rng);
        }
        _ => {}
    }

    for (name, color) in &entries {
        if mode == ColorMode::Off || !atty_stdout() {
            println!("{}", name);
        } else {
            let text_color = color.text_color();
            let text_r = text_color.r;
            let text_g = text_color.g;
            let text_b = text_color.b;

            let name_padded = format!("{:<25}", name);

            match mode {
                ColorMode::TrueColor => {
                    println!("\x1b[38;2;{};{};{};48;2;{};{};{}m {:<23} \x1b[0m",
                        text_r, text_g, text_b,
                        color.r, color.g, color.b,
                        name);
                }
                ColorMode::EightBit => {
                    let bg_idx = color.to_ansi8bit_value();
                    let fg_idx = text_color.to_ansi8bit_value();
                    println!("\x1b[38;5;{};48;5;{}m {:<23} \x1b[0m", fg_idx, bg_idx, name);
                }
                ColorMode::Off => {
                    println!("{}", name);
                }
            }
        }
    }
    Ok(())
}

pub fn run_mix(colorspace: &str, fraction: f64, color_args: &[String]) -> Result<()> {
    if color_args.is_empty() {
        return Err("Mix requires at least a base color".to_string());
    }

    let base_color = parse_color(&color_args[0])?;

    let rest: Vec<String> = color_args[1..].to_vec();
    let other_colors = if rest.is_empty() {
        // Read other colors from stdin
        let stdin = io::stdin();
        let mut colors = Vec::new();
        for line in stdin.lock().lines() {
            let line = line.map_err(|e| e.to_string())?;
            let line = line.trim();
            if line.is_empty() { continue; }
            let c = parse_color(line)?;
            colors.push(c);
        }
        colors
    } else {
        rest.iter().map(|s| parse_color(s)).collect::<Result<Vec<_>>>()?
    };

    for other in &other_colors {
        let result = mix_colors(&base_color, other, fraction, colorspace);
        print_color_hsl(&result);
    }

    Ok(())
}

pub fn run_paint(color_str: &str, bg_color_str: Option<&str>, bold: bool, italic: bool, underline: bool, no_newline: bool, text_args: &[String], mode: ColorMode) -> Result<()> {
    let fg = parse_color(color_str)?;
    let bg = if let Some(bg_str) = bg_color_str {
        Some(parse_color(bg_str)?)
    } else {
        None
    };

    if text_args.is_empty() {
        // Read from stdin
        let stdin = io::stdin();
        let mut lines: Vec<String> = Vec::new();
        for line in stdin.lock().lines() {
            let line = line.map_err(|e| e.to_string())?;
            lines.push(line);
        }
        let text = lines.join("\n");
        let colored = colorize_text(&text, &fg, bg.as_ref(), bold, italic, underline, mode);
        if no_newline {
            print!("{}", colored);
        } else {
            println!("{}", colored);
        }
    } else {
        let text = text_args.join(" ");
        let colored = colorize_text(&text, &fg, bg.as_ref(), bold, italic, underline, mode);
        if no_newline {
            print!("{}", colored);
        } else {
            println!("{}", colored);
        }
    }

    Ok(())
}

