            let mut cmd = Cli::command();
            cmd.print_help().unwrap();
            println!();
            return;
        }
        Some(Commands::Color { colors }) => {
            run_color(&colors, color_mode)
        }
        Some(Commands::Colorblind { cb_type, colors }) => {
            run_colorblind(&cb_type, &colors)
        }
        Some(Commands::Colorcheck) => {
            run_colorcheck(color_mode)
        }
        Some(Commands::Complement { colors }) => {
            run_complement(&colors)
        }
        Some(Commands::Darken { amount, colors }) => {
            run_darken(amount, &colors)
        }
        Some(Commands::Desaturate { amount, colors }) => {
            run_desaturate(amount, &colors)
        }
        Some(Commands::Distinct { count, colors }) => {
            run_distinct(count, &colors)
        }
        Some(Commands::Format { format_type, colors }) => {
            run_format(&format_type, &colors)
        }
        Some(Commands::Gradient { count, colorspace, colors }) => {
            run_gradient(count, &colorspace, &colors)
        }
        Some(Commands::Gray { lightness }) => {
            run_gray(lightness)
        }
        Some(Commands::Lighten { amount, colors }) => {
            run_lighten(amount, &colors)
        }
        Some(Commands::List { sort }) => {
            run_list(&sort, color_mode)
        }
        Some(Commands::Mix { colorspace, fraction, colors }) => {
            run_mix(&colorspace, fraction, &colors)
        }
        Some(Commands::Paint { bg_color, bold, italic, underline, no_newline, color, text }) => {
            run_paint(&color, bg_color.as_deref(), bold, italic, underline, no_newline, &text, color_mode)
        }
        Some(Commands::Pick) => {
            run_pick()
        }
        Some(Commands::Random { strategy, count }) => {
            run_random(&strategy, count)
        }
        Some(Commands::Rotate { degrees, colors }) => {
            run_rotate(degrees, &colors)
        }
        Some(Commands::Saturate { amount, colors }) => {
            run_saturate(amount, &colors)
        }
        Some(Commands::Set { property, value, colors }) => {
            run_set(&property, value, &colors)
        }
        Some(Commands::SortBy { sort_order, reverse, unique, colors }) => {
            run_sort_by(&sort_order, reverse, unique, &colors)
        }
        Some(Commands::Textcolor { colors }) => {
            run_textcolor(&colors)
        }
        Some(Commands::ToGray { colors }) => {
            run_to_gray(&colors)
        }
    };

    if let Err(e) = result {
        eprintln!("[pastel error]: {}", e);
        process::exit(1);
    }
}
